Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String s = in.next();
        int maxLen = -1, currentLen = 0;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == '_') {
                if (currentLen > maxLen) maxLen = currentLen;
                currentLen = 0;
            } else if (ch != '(' && ch != ')') {
                currentLen++;
            } else {
                if (currentLen > maxLen) maxLen = currentLen;
                currentLen = 0;
                i++;
                while (i < n && s.charAt(i) != ')') i++;
            }
        }
        if (currentLen > maxLen) maxLen = currentLen;

        int wordsCount = 0, wordSize = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '(') {
                i++;
                while (i < n && s.charAt(i) != ')') {
                    if (s.charAt(i) == '_') {
                        if (wordSize > 0) wordsCount++;
                        wordSize = 0;
                    } else if (s.charAt(i) != '_') {
                        wordSize++;
                    }
                    i++;
                }
                if (wordSize > 0) wordsCount++;
                wordSize = 0;
            }
        }
        System.out.println(maxLen + " " + wordsCount);
    }
}
